// Extrai o conteúdo do arquivo CSV lido
let csvContent = '';
const binaryObj = $input.first().binary;

if (binaryObj) {
  // Pega a chave binária (geralmente 'data')
  const binaryKey = binaryObj.data ? 'data' : Object.keys(binaryObj)[0];
  if (binaryKey && binaryObj[binaryKey]) {
    csvContent = Buffer.from(binaryObj[binaryKey].data, 'base64').toString('utf-8');
  }
}

if (!csvContent && $input.first().json) {
  csvContent = $input.first().json.content || '';
}

const lines = csvContent.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
if (lines.length <= 1) {
  return [];
}

// Remove BOM UTF-8 se existir
const headers = lines[0].replace(/^\uFEFF/, '').split(';').map(h => h.trim());
const records = [];

for (let i = 1; i < lines.length; i++) {
  const cols = lines[i].split(';');
  const row = {};
  headers.forEach((h, idx) => {
    row[h] = cols[idx] ? cols[idx].trim() : '';
  });
  records.push(row);
}

// Filtrar apenas os que ainda estão PENDENTES (não enviados)
const pendentes = records.filter(r => (r['Status Envio'] || 'Pendente').toLowerCase() === 'pendente');

// LIMITE DE SEGURANÇA: Exatamente 40 contatos por dia!
const loteDoDia = pendentes.slice(0, 40);

return loteDoDia.map((item, index) => ({
  json: {
    ...item,
    indiceDoLote: index + 1,
    totalDoLote: loteDoDia.length
  }
}));

// LISTA DE SAUDAÇÕES ALEATÓRIAS (Spintax)
const saudacoes = [
  "Olá, tudo bem?",
  "Oi, tudo bem?",
  "Bom dia, tudo bem?",
  "Olá, bom dia, tudo bem?",
  "Olá, bom dia!",
  "Olá, como vai?",
  "Boa tarde, tudo bem?",
  "Oi, boa tarde, tudo bem?",
  "Olá, boa tarde!",
  "Oi, tudo joia por aí?",
  "Olá, tudo joia?"
];

// Sorteia uma saudação diferente a cada mensagem
const saudacao = saudacoes[Math.floor(Math.random() * saudacoes.length)];

// Pega o nome tratado e limpo
let nome = $json["Nome Tratado (Para Mensagem)"] || $json["Nome Original"] || "";

// Monta a mensagem final: "[Saudação aleatória] [Nome Limpo]?"
// Exemplo: "Olá, tudo bem? Dra. Leticia Matos?"
const mensagem = `${saudacao} ${nome}?`;

// DELAY NÃO-LINEAR ALEATÓRIO: Entre 120s (2 min) e 210s (3m30s)
// Exemplo: 137s, 194s, 151s, 208s...
const delayMinimo = 120;
const delayMaximo = 210;
const delaySegundos = Math.floor(Math.random() * (delayMaximo - delayMinimo + 1)) + delayMinimo;

// Formata o número de telefone (DDI 55 + DDD + 9XXXX-XXXX)
const ddd = String($json["DDD"] || "").replace(/\D/g, "");
const numero = String($json["Número"] || "").replace(/\D/g, "");
const telefoneCompleto = `55${ddd}${numero}`;

return {
  json: {
    ...$json,
    whatsappDestino: telefoneCompleto,
    mensagemFinal: mensagem,
    delaySegundosEspera: delaySegundos,
    delayMinutosFormatado: `${(delaySegundos / 60).toFixed(1)} min`,
    horarioDisparo: new Date().toLocaleTimeString('pt-BR')
  }
};
